    icon: "Heart",
    summary: "قصة تنازل الحسن بن علي رضي الله عنهما عن الخلافة لمعاوية علي بشروط صلح لصون دماء المسلمين، والعبرة فيها أن المصالحة عند الحاجة من حكمة الشريعة لا ضعف، مع الاقتصار على الثابت وترك الزيادات الشعبية.",
    full_content: `الحسن بن علي بن أبي طالب رضي الله عنهما — سبط رسول الله ﷺ، وقد توفي النبي ﷺ وهو صبي فقال في الصحيح من أمره ﷺ: «إن ابني هذا سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين».

**بعد مقتل علي:**
تولّى الحسن الخلافة في وقت اضطراب، واشتد الخلاف بين أهل العراق وأهل الشام. وكان في جيش أهل العراق من يطلب القتال ومن يميل إلى الصلح.

**صلح الحسن:**
رأى الحسن أن استمرار القتال يُهلك الأمة، فتنازل عن الخلافة لمعاوية مع شروط عُرفت «صلح الحسن»، منها أن الخلافة تنتقل إلى معاوية وعدم اضطهاد أصحاب علي رضي الله عنه.

**العبرة في التاريخ:**
يُروى أهل السير أن صلح الحسن فتح بواب الصلح في الخلاف، وأن الحسن ترك الخلافة وانصرف إلى العبادة والعلم والزهد. ويُستفاد من هذا الموقف في أن صون الدم أعلى من التشبث بالمنصب عند الحاجة.

**العبرة:**
الحسن يُعلّم أن المصالحة قد تكون من حكمة الشريعة لصون دماء المسلمين، وأن وحدة الأمة أهم من الإثبات الشخصية، مع الاقتصار على الثابت في التفاصيل وترك التكلّ الشعبي في الأحكام.`,
    key_lessons: [
      "صون الدم أعلى من التشبث بالمنصب؛ فالحسن تنازل عن الخلافة لئلا تُهلك الأمة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى تقديم المصلحة على الحق لا على الهوى.",
      "المصالحة من حكمة الشريعة؛ وقد بَشّر النبي ﷺ بصلح الحسن قبل وقوع الفتنة، ويُستفاد منه أن الحكمة قد تتطلب تضحية للأمة؛ مع مراعاة الدليل لا الشهرة.",
      "الحلم مع الشجاعة؛ فالحسن كان شجاعاً في الحرب حليماً في الصلح، ويُذكّر ويُستفاد منه ضبط الغضب حين يُراد الحق؛ مع الاقتصاد في الروايات.",
      "وحدة الأمة أهم من الإثبات؛ فصلح الحسن فتح بوابً للصلح في الخلاف، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى سلوك يومي ميسر مع الانتماء للمذهب السلمي في الخلافات."
    ],
    related_figures: ["علي بن أبي طالب", "معاوية بن أبي سفيان", "النبي محمد ﷺ", "الحسين بن علي"],
    sources: ["صحيح البخاري", "سيرة ابن إسحاق", "الاستيعاب — ابن عبد البر", "تاريخ الطبري"],
