  {
    id: 118,
    slug: "nafi-golden-chain-hadith-r49",
    title: "نافع — السلسلة الذهبية في الحديث",
    category: "علم",
    era: "تابعي",
    icon: "Link",
    summary: "قصة نافع مولى ابن عمر رضي الله عنهما ودوره في نقل الحديث عبر «السلسلة الذهبية» إلى الإمام مالك، والعبرة فيها أن نقل العلم أمانة لا شهرة، مع الاقتصار على الثابت في علم الرجال.",
    full_content: `نافع — مولى عبد الله بن عمر، من أثبت رواة الحديث في المدينة، واشتهر بورعه وضبطه.

**الرواية:**
روى عن ابن عمر بكثرة، وروى عنه الإمام مالك بن أنس، فصارت سلسلة: «مالك عن نافع عن ابن عمر» من أشهر سلاسل الإسناد، وسمّيت «السلسلة الذهبية» لثبوتها.

**الورع:**
كان يُوصف بالتقوى والضبط، ولم يُعرف بكثرة التصنيف بل بإتقان الرواية. وقال بعض أهل العلم: «ما رأيت أحداً أورع من نافع».

**العبرة:**
نافع يُعلّم أن حمل الأمانة في الحديث يحتاج ورعاً وضبطاً، وأن العلم يُبنى على الثقة لا على كثرة الرواة.`,
    key_lessons: [
      "نقل العلم أمانة؛ فنافع روى عن ابن عمر بضبط، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى طلب العلم بلا تعصب.",
      "السلسلة الذهبية تُعلّم الثبوت؛ فمالك عن نافع عن ابن عمر من أثبت السلاسل، ويُستفاد منه ضبط الغضب حين يُبتلى المسلم؛ مع مراعاة الدليل لا الشهرة.",
      "الورع شرط الرواية؛ وُصف بأنه من أورع الناس، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "العلم يُبنى على الثقة؛ فاشتهر بالضبط لا بالكثرة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى سلوك يومي ميسر."
    ],
    related_figures: ["عبد الله بن عمر", "مالك بن أنس", "الإمام مالك"],
    sources: ["تهذيب الكمال — المزي", "طبقات ابن سعد", "الجرح والتعديل — ابن أبي حاتم"],
    tags: ["نافع", "حديث", "سلسلة ذهبية", "مالك"],
    is_approved: true,
    trust_level: "general_reasoning",
    editorial_review_status: "unreviewed",
    last_updated_at: "2026-07-27T00:00:00.000Z"
  },
  {
    id: 119,
    slug: "mamun-ahmad-mihna-r49",
    title: "المأمون وأحمد — المحنة والثبات",
    category: "تاريخ",
    era: "عباسي",
    icon: "Shield",
    summary: "قصة محنة خلق القرآن في عهد المأمون وثبات الإمام أحمد بن حنبل رحمه الله، والعبرة فيها أن الحق لا يُباع بمنصب، مع الاقتصار على الثابت في التاريخ.",
    full_content: `المحنة — اختبار أئمة الحديث في عهد الخليفة العباسي المأمون — ومن أبرز من ثبت فيها الإمام أحمد بن حنبل.

**السياق:**
دعا المأمون إلى قول بخلق القرآن، فامتنع كثير من العلماء. وكان أحمد يرى أن القرآن كلام الله غير مخلوق، فرفض الموافقة على ما خالف ذلك.

**الثبات:**
سُجن أحمد وُجدّد فيه العذاب، ولم يزل يرفض القول بخلق القرآن. وقال فيما ينقله أهل السير: «لو كان بيني وبين الجنة سيفٌ لقاتلت حتى أدخلها».

**الأثر:**
بعد وفاة المأمون تراجعت المحنة، وصار أحمد مرجعاً لأهل السنة في الثبات على العقيدة. ويُستفاد منه أن العلماء يحملون الأمانة حتى في أشد الابتلاء.

**العبرة:**
أحمد يُعلّم أن الحق لا يُباع بمنصب، وأن الصبر على البلاء في سبيل العقيدة من أعظم المواقف.`,
    key_lessons: [
      "الحق لا يُباع بمنصب؛ فأحمد رفض موافقة المأمون، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على العقيدة بلا غلو.",
      "الصبر على البلاء فضيلة؛ فسُجن وُعذّب ولم يزل ثابتاً، ويُستفاد منه ضبط الغضب حين يُبتلى المسلم؛ مع مراعاة الدليل لا الشهرة.",
      "العلماء حملة الأمانة؛ فتحمّل المحنة لأجل السنة، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "القرآن كلام الله؛ فثبته على غير مخلوق، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى سلوك يومي ميسر."
    ],
    related_figures: ["أحمد بن حنبل", "المأمون", "محمد بن نصر المروزي"],
    sources: ["سير أعلام النبلاء — الذهبي", "طبقات الحنابلة — ابن أبي يعلى", "المحنة — أبو الفرج"],
    tags: ["أحمد بن حنبل", "المحنة", "عقيدة", "عباسي"],
    is_approved: true,
    trust_level: "general_reasoning",
    editorial_review_status: "unreviewed",
    last_updated_at: "2026-07-27T00:00:00.000Z"
  }

