    slug: "asma-bint-abi-bakr-dhat-al-nitaqayn-r51",
    title: "أسماء بنت أبي بكر — ذات النطاقين",
    category: "صحابة",
    era: "مدني",
    icon: "Heart",
    summary: "قصة أسماء بنت أبي بكر رضي الله عنها وصبرها في الهجرة ونقلها الزاد للنبي ﷺ وأبي بكر، والعبرة فيها أن الإيمان يُثبت في الشدة لا في الرخاء، مع الاقتصار على الثابت في السيرة.",
    full_content: `أسماء بنت أبي بكر الصديق — من الصحابيات الجليلات، لُقّبت بذات النطاقين لقطعها نطاقين لحمل الزاد في الهجرة.

**الهجرة:**
روى أنها كانت تحمل الطعام والماء إلى غار ثور ليلاً، فقطعت نطاقين من نطاقها لربط الزاد، فسُمّيت ذات النطاقين.

**الصبر:**
عاشت طويلاً بعد النبي ﷺ، وروت عنه وعن أبيها، واشتهرت بالزهد والورع.

**العبرة:**
أسماء تُذكّر أن المرأة المؤمنة شريك في نصرة الدين، وأن الصبر على المشقة من أعظم أعمال الصحابيات.`,
    key_lessons: [
      "الصبر في نصرة الدين؛ فحملت الزاد إلى الغار بلا جزع، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الإخلاص في العمل.",
      "التضحية باليسير؛ فقطعت نطاقها لربط الطعام، ويُستفاد منه بذل ما نستطيع في سبيل الله؛ مع مراعاة الدليل لا الشهرة.",
      "الزهد بعد الصحبة؛ فعاشت طويلاً بورع، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "المرأة المؤمنة شريك؛ فنصرت الهجرة بعمل ظاهر، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى المسؤولية في البيت والمجتمع."
    ],
    related_figures: ["أبو بكر الصديق", "النبي محمد ﷺ", "عائشة أم المؤمنين"],
