      "العلم في الشام؛ فكان مرجعاً قبل المذاهب، ويُستفاد منه تنوع الفقه المعتبر؛ مع مراعاة الدليل لا الشهرة.",
      "الاتباع قبل الابتداع؛ فبنى على أقوال الصحابة، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الإمامة أمانة؛ فكان زاهداً في الدنيا، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى تواضع طالب العلم."
