    slug: "ibn-sirin-dreams-fiqh-r52",
    title: "محمد بن سيرين — تفسير الرؤيا والفقه",
    category: "تاريخ",
    era: "تابعي",
    icon: "Eye",
    summary: "قصة محمد بن سيرين رحمه الله وعلمه في تفسير الرؤيا والفقه وورعه، والعبرة فيها أن العلم يُقاس بالورع والضبط لا بالكثرة، مع الاقتصار على الثابت في السير.",
    full_content: `محمد بن سيرين — من أئمة التابعين في البصرة، اشتهر بتفسير الرؤيا والفقه والحديث.

**تفسير الرؤيا:**
روى أهل العلم أنه كان أعلم أهل زمانه بتفسير الرؤيا، مع التثبت في الرواية.

**الورع:**
اشتهر بالورع في المال والفتوى، ويُوصف بأنه كان شديد الحذر في القول.

**العبرة:**
ابن سيرين يُذكّر أن العلم بلا ورع يُورث غروراً، وأن تفسير الرؤيا يحتاج إلى علم وورع معاً.`,
    key_lessons: [
      "الورع في القول؛ فكان حذراً في الفتوى، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى التثبت قبل القول.",
      "تفسير الرؤيا بعلم؛ فاشتهر بضبطه، ويُستفاد منه ألا يُتسرَّع في التأويل؛ مع مراعاة الدليل لا الشهرة.",
      "العلم والورع يجتمعان؛ فكان عالماً زاهداً، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "ضبط الرواية؛ فاشتهر بالتثبت، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى أمانة نقل العلم."
    ],
    related_figures: ["الحسن البصري", "أنس بن مالك", "عكرمة"],
