      "العلم يُرفع صاحبه؛ فأخذ عنه الناس، ويُستفاد منه أن القرآن شرف؛ مع مراعاة الدليل لا الشهرة.",
      "الفقه مع القراءة؛ فاشتهر بعلمه، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "التواضع في العلم؛ فكان يُعلّم الناس، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى نشر الخير بلا غرور."
