      "الرواية أساس التفسير؛ فروى عن ابن عباس، ويُستفاد منه أهمية السند؛ مع مراعاة الدليل لا الشهرة.",
      "الاجتهاد بضوابط؛ فاشتهر باجتهاده المرتبط بالرواية، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
