    summary: "قصة جابر بن عبد الله رضي الله عنه ومسألة ميراث البنات في الإسلام، والعبرة فيها أن الشريعة جاءت بحقوق محددة للنساء، مع الاقتصار على الثابت في السيرة.",
    full_content: `جابر بن عبد الله — صحابي جليل، شهد بدراً وأُحداً وغيرهما، واشتهرت قصته في ميراث البنات.

**المسألة:**
روى في صحيح مسلم أنه جاء إلى النبي ﷺ يسأل عن ميراث بناته بعد وفاة أبيهن.

**الجواب:**
بَيَّن له النبي ﷺ نصيب البنات في الميراث وفق ما أنزل الله.

**العبرة:**
جابر يُذكّر أن حقوق الميراث من ثوابت الشريعة، وأن السؤال عنها من باب طلب العلم الشرعي.`,
    key_lessons: [
      "حقوق الميراث ثابتة؛ فبَيَّن النبي ﷺ نصيب البنات، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى معرفة الأحكام قبل التطبيق.",
      "السؤال عن العلم؛ فجاء جابر يسأل، ويُستفاد منه أن طلب العلم واجب؛ مع مراعاة الدليل لا الشهرة.",
      "عدل الشريعة؛ فجاءت بحقوق محددة للنساء، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الورع في المال؛ فسأل عن الميراث بصدق، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى أمانة في الحقوق."
    ],
    related_figures: ["النبي محمد ﷺ", "عبد الله بن عبد الله", "سعد بن معاذ"],
