    slug: "umm-uthman-ibn-mazun-r54",
    title: "أم عثمان بن مظعون — صبر على البلاء",
    category: "صحابة",
    era: "مكي",
    icon: "Heart",
    summary: "قصة أم عثمان بن مظعون رضي الله عنها وصبرها على فقد زوجها، والعبرة فيها أن الصبر على البلاء من صفات المؤمنين، مع الاقتصار على الثابت في السيرة.",
    full_content: `أم عثمان بن مظعون — من صحابيات مكة، زوجة عثمان بن مظعون رضي الله عنهما.

**البلاء:**
روى أهل السير أنها فقدت زوجها عثمان بن مظعون في حياتها، وصبرت على البلاء.

**الصبر:**
اشتهرت بالصبر والرضا، وكانت من المؤمنات الصادقات.

**العبرة:**
أم عثمان تُذكّر أن الصبر على فقد الأحباب من صفات المؤمنين، وأن الأجر عند الله.`,
    key_lessons: [
      "الصبر على البلاء؛ ففقدت زوجها وصبرت، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الرضا بقدر الله.",
      "الإيمان في الشدة؛ فكانت من المؤمنات الصادقات، ويُستفاد منه أن الإيمان يُختبر بالبلاء؛ مع مراعاة الدليل لا الشهرة.",
      "الأجر عند الله؛ فالصبر مُثاب عليه، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الرضا بالقدر؛ فاشتهرت بالصبر، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى التوكل على الله."
    ],
