    full_content: `سُمَيَّة بنت خياط — من أوائل من آمن، أم عمّار بن ياسر، واشتهرت بصبرها على العذاب.

**البلاء:**
روى أهل السير أن قريشاً عذّبتها وعمّارها وياسراً على إسلامهم.

**الشهادة:**
عُذّبت حتى استُشهدت، فكانت أول شهيدة في الإسلام على المشهور.

**العبرة:**
سُمَيَّة تُذكّر أن المرأة المؤمنة قد تُبلّى وتثبت، وأن الشهادة في سبيل الله شرف لا يُحدّ بالجنس.`,
