      "الشهادة شرف؛ فكانت أول شهيدة، ويُستفاد منه أن الموت في سبيل الله مُثاب عليه؛ مع مراعاة الدليل لا الشهرة.",
      "الأسرة المؤمنة؛ فعذّبت مع ياسر وعمّار، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الإيمان لا يُقاس بالجنس؛ فثبتت حتى الشهادة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى إخلاص النية."
