    slug: "abdullah-ibn-masud-quran-reciter-r57",
    title: "عبد الله بن مسعود — حامل القرآن",
    category: "صحابة",
    era: "مدني",
    icon: "BookOpen",
    summary: "قصة عبد الله بن مسعود رضي الله عنه ودوره في تعليم القرآن والسنة، والعبرة فيها أن حامل العلم أمانة يُبلّغها بلا تحريف، مع الاقتصار على الثابت في السيرة.",
    full_content: `عبد الله بن مسعود — من أوائل من آمن، واشتهر بتلاوته للقرآن وتعليمه.

**التعليم:**
روى في صحيح مسلم أن النبي ﷺ قال: «خذوا القرآن من أربعة، ومنهم عبد الله بن مسعود».

**الورع:**
اشتهر بورعه وعلمه، وكان من أثبت الصحابة في الرواية.

**العبرة:**
ابن مسعود يُذكّر أن حامل القرآن أمانة، وأن التعليم من أعظم أعمال الدين.`,
    key_lessons: [
      "حمل القرآن؛ فاشتهر بتلاوته، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى ضبط الرواية.",
      "التعليم أمانة؛ فعلّم أهل الكوفة، ويُستفاد منه أن العلم يُبلَّغ بلا تحريف؛ مع مراعاة الدليل لا الشهرة.",
      "الورع في العلم؛ فاشتهر بزهده، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "الرواية بأمانة؛ فروى عن النبي ﷺ، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى صيانة السنة."
    ],
