    title: "عبد الله بن عباس — حبر الأمة",
    category: "صحابة",
    era: "مدني",
    icon: "GraduationCap",
    summary: "قصة عبد الله بن عباس رضي الله عنهما وتفسيره للقرآن، والعبرة فيها أن الشاب المؤمن قد يبلغ منزلة العالم إذا صدق مع الله، مع الاقتصار على الثابت في السيرة.",
    full_content: `عبد الله بن عباس — ابن عم النبي ﷺ، واشتهر بتفسيره للقرآن.

**الدعاء:**
روى في صحيح البخاري أن النبي ﷺ دعا له: «اللهم فقّهه في الدين وعلّمه التأويل».

**التفسير:**
اشتهر بتفسير القرآن، وروى عنه التابعون والأئمة.

**العبرة:**
ابن عباس يُذكّر أن الشاب المؤمن قد يبلغ منزلة العالم، وأن التفسير يحتاج إلى علم وورع.`,
    key_lessons: [
      "التفسير بورع؛ فاشتهر بتأويل القرآن، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى ضبط الرواية.",
      "دعاء النبي ﷺ؛ فدعا له بالفقه، ويُستفاد منه أن العلم منحة؛ مع مراعاة الدليل لا الشهرة.",
      "الشاب العالم؛ فتعلّم في صغره، ويُذكّر أن العبرة بالأثر لا بالشعار؛ مع الاقتصاد في الروايات.",
      "حلقة العلم؛ فروى عنه التابعون، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى صيانة السنة."
    ],
