    full_content: `سلمان الفارسي — من أبرز الصحابة الذين طلبوا الحق عبر أديان وبلدان.

**البحث:**
روى في صحيح البخاري أنه كان مجوسياً ثم نصرانياً ثم وصل إلى الإسلام بعد رحلة طويلة.

**المدينة:**
اقترح على النبي ﷺ حفر الخندق يوم الأحزاب، فكان من أسباب النصر.

**العبرة:**
سلمان يُذكّر أن طلب الحق يستحق الصبر، وأن المؤمن قد يُبتلى قبل أن يجد الطريق.`,
    key_lessons: [
      "طلب الحق؛ فسافر بين الأديان حتى وصل للإسلام، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الصبر في البحث.",
      "العمل بالنصيحة؛ فاقترح الخندق، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الصبر على البلاء؛ فابتُلي في طريقه، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد."
    ],
