      "الشهادة في سبيل الله؛ فاستُشهدت أمه سمية، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الصبر على الأذى؛ فصبر على التعذيب، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
