    slug: "musab-ibn-umayr-dawah-r59",
    title: "مصعب بن عمير — داعية المدينة",
    category: "صحابة",
    era: "مدني",
    icon: "Megaphone",
    summary: "قصة مصعب بن عمير رضي الله عنه ودعوته في المدينة قبل الهجرة، والعبرة فيها أن الدعوة تحتاج إلى علم وصبر، مع الاقتصار على الثابت في السيرة.",
    full_content: `مصعب بن عمير — من أوائل من آمن، واشتهر بدعوته في المدينة قبل الهجرة.

**الدعوة:**
روى في صحيح البخاري أن النبي ﷺ بعثه إلى المدينة ليعلم الناس القرآن والإسلام.

**العلم:**
كان من أجمل الشباب في مكة، ثم اختار الإسلام على الدنيا.

**العبرة:**
مصعب يُذكّر أن الدعوة تحتاج إلى علم وصبر، وأن العبرة بالأثر لا بالمظهر.`,
    key_lessons: [
      "الدعوة بالعلم؛ فبعثه النبي ﷺ إلى المدينة، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى ضبط الرواية.",
      "التضحية في سبيل الله؛ فترك الدنيا، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقي مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الشهادة في سبيل الله؛ فاستُشهد في أحد، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد."
    ],
