    title: "عائشة أم المؤمنين — علم وذكاء",
    category: "صحابة",
    era: "مدني",
    icon: "BookOpen",
    summary: "قصة عائشة رضي الله عنها وعلمها وذكائها، والعبرة فيها أن المرأة المؤمنة قد تكون مرجعاً في العلم، مع الاقتصار على الثابت في السيرة.",
    full_content: `عائشة أم المؤمنين — زوج النبي ﷺ، واشتهرت بعلمها وذكائها.

**العلم:**
روى في صحيح البخاري أن الصحابة كانوا يرسلون إليها في المسائل، وروت آلاف الأحاديث.

**الذكاء:**
عُرفت بفهمها السريع وحفظها القوي، وكانت من أعلم النساء.

**العبرة:**
عائشة تُذكّر أن المرأة المؤمنة قد تكون مرجعاً في العلم، وأن طلب العلم من تمام الإيمان.`,
    key_lessons: [
      "طلب العلم؛ فروت آلاف الأحاديث، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى الثبات على التوحيد.",
      "الذكاء في الفهم؛ فعُرفت بفهمها، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الوفاء للرسالة؛ فبقيت مع النبي ﷺ، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
      "الدعوة بالعلم؛ فكان الصحابة يرسلون إليها، مع تقديم الثابت على القصص الواهية؛ ويُترجم ذلك إلى العمل بلا توانٍ."
    ],
