      "الحرية في الإيمان؛ فاختار الإسلام، ويُستفاد منه أن العبرة بالأثر لا بالمكانة؛ مع مراعاة الدليل لا الشهرة.",
      "الشجاعة في الجهاد؛ فشارك في المعارك، ويُذكّر أن الإيمان قرارٌ حر؛ مع الاقتصاد في الروايات.",
